import java.util.Arrays;

public class ArrayPracticePatterns {
    public static void reverseInPlace(int[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
    }

    public static boolean isSorted(int[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] > arr[i + 1]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] data = {1, 2, 3, 4, 5};
        System.out.println("Initially Sorted: " + isSorted(data));

        reverseInPlace(data);
        System.out.println("Reversed in-place: " + Arrays.toString(data));
        System.out.println("Sorted after reversal: " + isSorted(data));
    }
}

