practiceProblems.solutionCode:
public class Main {
    public static int countDistinct(int[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            boolean isDuplicate = false;
            for (int j = 0; j < i; j++) {
                if (arr[i] == arr[j]) {
                    isDuplicate = true;
                    break;
                }
            }
            if (!isDuplicate) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] data = {5, 2, 5, 8, 2, 9};
        System.out.println("Distinct Count: " + countDistinct(data));
    }
}

