public class Main {
    public static int countUniqueSorted(int[] arr) {
        if (arr.length == 0) return 0;
        int count = 1;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] != arr[i + 1]) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] data = {1, 1, 2, 2, 2, 3, 4, 4};
        System.out.println("Unique Sorted Count: " + countUniqueSorted(data));
    }
}
